canvas.tokens.controlled.forEach(async (token) => {
	let message = "";
	let tick = Math.floor(token.actor.system.health.total / 2);
	let marker = Math.floor(token.actor.system.health.total / 2);
	let previous = token.actor.system.health.value;
	let tempHp = token.actor.system.tempHp.value;

	if(tempHp > 0)
	{
		tempHp -= tick;
		if(tempHp < 0)
		{
			await token.actor.modifyTokenAttribute("health.value", token.actor.system.health.value + tempHp, false, false);
			await token.actor.modifyTokenAttribute("tempHp.value", 0, false, false);
		}
		else
		{
			await token.actor.modifyTokenAttribute("tempHp.value", tempHp, false, false);
		}
	}
	else
	{
		await token.actor.modifyTokenAttribute("health.value", token.actor.system.health.value + tick, false, false);
	}

	message += "<b>" + token.actor.name + "</b> was healed for half max HP (-" + tick + " hp)";



	ChatMessage.create({
	user: game.user._id,
	content: message
	});
})
